41	func Keys() []Key {
42		return []Key{
43			KeyEnter, KeyEscape, KeyInterrupt, KeyTab, KeyBackTab, KeyUp,
44			KeyDown, KeyLeft, KeyRight, KeyPageUp, KeyPageDown, KeyBackspace,
45		}
46	}
