48	// ParseKey maps a caller's string to a Key by exact, case-sensitive lookup.
49	// Trimming or folding here would widen a closed set into a fuzzy one.
50	func ParseKey(name string) (Key, error) {
51		k := Key(name)
52		if _, ok := tmuxKeys[k]; !ok {
53			return "", ErrUnknownKey
54		}
55		return k, nil
56	}
