58	// MaxTypeBytes bounds one typed message (spec FR-004).
59	const MaxTypeBytes = 16384
60	
61	var (
62		ErrUnknownKey   = errors.New("that is not a key the session page offers")
63		ErrInputTooLong = errors.New("typed text is longer than the bound")
64		ErrInputInvalid = errors.New("typed text holds a control character or is not UTF-8")
65	
66		// ErrSubmitFailed means the text reached the pane and the Enter after it
67		// did not. It is not a failure to deliver, and a caller must not offer a
68		// retry that types the text a second time (spec 018 review #4).
69		ErrSubmitFailed = errors.New("the text was typed but not submitted")
70	)
71	
72	// ValidateTyped applies FR-004 to text the caller has already CRLF-normalised.
73	// The control-character refusal is what keeps a pasted "\x1b[201~" from ending
74	// the bracketed paste early and letting the remainder run as keystrokes.
75	func ValidateTyped(text string) error {
76		if text == "" {
77			return ErrEmptyPrompt
78		}
79		if len(text) > MaxTypeBytes {
80			return ErrInputTooLong
81		}
82		if !utf8.ValidString(text) {
83			return ErrInputInvalid
84		}
85		for i := 0; i < len(text); i++ {
86			b := text[i]
87			if (b < 0x20 && b != '\t' && b != '\n') || b == 0x7f {
88				return ErrInputInvalid
89			}
90		}
91		return nil
92	}
