94	// Type delivers operator text into a session by bracketed paste, then presses
95	// Enter when submit is true. The paste is bracketed for every session whatever
96	// it runs: research.md R1 measured that a plain paste submits line one early on
97	// Claude Code, so a per-runtime choice here would break multi-line text there.
98	//
99	// Input is never gated on what the pane shows, and the text is never audited,
100	// logged or named in an error, for the reason Prompt's is not.
101	func (m *Manager) Type(ctx context.Context, s Session, text string, submit bool) error {
102		if err := guardDelivery(s); err != nil {
103			return fmt.Errorf("type into session: %w", err)
104		}
105		if err := ValidateTyped(text); err != nil {
106			return fmt.Errorf("type into session %s: %w", s.ID, err)
107		}
108	
109		// Held across the paste and the Enter, so a key or another message cannot
110		// land between them.
111		unlock := m.lockSession(s.ID)
112		defer unlock()
113	
114		if err := m.stillLive(s); err != nil {
115			return fmt.Errorf("type into session %s: %w", s.ID, err)
116		}
117		if err := m.tmux.PasteBracketed(ctx, s.TmuxName(), []byte(text)); err != nil {
